INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (9, 15, 'theory', 'Quiz: window functions');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 15, 0, 'How does a window function differ from an aggregate with GROUP BY?', '["It doesn''t", "It doesn''t collapse rows: the result is calculated for each row separately", "It works only with numbers", "It''s faster"]', 1, 'GROUP BY turns a group into a single row, while a window function keeps all the rows and adds a calculated column.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 15, 1, 'What does SUM(x) OVER (ORDER BY id) return for x values 10, 20, 30?', '["60, 60, 60", "10, 30, 60", "10, 20, 30", "30, 50, 60"]', 1, 'With ORDER BY the default frame runs from the start of the window to the current row, so we get the running total 10, 30, 60.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 15, 2, 'The values in a ranking are 90, 85, 85, 70. What places will RANK() give in descending order?', '["1, 2, 3, 4", "1, 2, 2, 4", "1, 2, 2, 3", "1, 1, 1, 1"]', 1, 'RANK gives equal values the same place and skips the next one: 1, 2, 2, 4. DENSE_RANK would give 1, 2, 2, 3, and ROW_NUMBER 1, 2, 3, 4.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 15, 3, 'How do you get the three most expensive products in each category?', '["LIMIT 3", "ROW_NUMBER() OVER (PARTITION BY category ORDER BY price DESC) in a subquery/CTE and the condition rn <= 3 outside", "GROUP BY category HAVING COUNT(*) <= 3", "ORDER BY category LIMIT 3"]', 1, 'LIMIT restricts the whole result. A window function does the numbering within groups, and the condition on it must be written in an outer query.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 15, 4, 'What does LAG(x) return for the first row of the window?', '["0", "NULL", "The value of the very first row", "An error"]', 1, 'There is no previous row, so LAG returns NULL unless a default value is given as the third argument.');
